INSERT INTO `wp_kss_activities` (`id`, `title`, `description`, `photo`) VALUES
(1, 'Educate Club exhibition', 'Members of the Educate Club showed their projects to the school community.', '/wp-content/plugins/kahinju-core/assets/gallery/kahinju-m3-04.jpg'),
(3, 'Student\'s Handover', 'Empowering Students leaders at Kahinju senior secondary school is central to nurturing disciplined, responsible and future-ready citizens. students leadership contributes to positive school culture, confidence buildung and academic success', '/wp-content/uploads/2026/11/WhatsApp-Image-2026-11-20-at-4.00.10-PM.jpeg'),
(5, 'The School Tour', 'Student\'s Leisure events at Kasese Equator. This enables them to be familiar with parts of the World', '/wp-content/uploads/2026/11/WhatsApp-Image-2026-11-20-at-3.59.59-PM-1.jpeg');
