(3, 'KSS-2026-0003', 'Kyaboona Benard', 'Senior Five (S.5) - A-Level', 'About ss', 'ISINGOMA JOSEPH', '0761602932', '', 'please consider me', 'replied', 'Dear ISINGOMA JOSEPH,\r\nWe have received the application of Kyaboona Benard to Senior Five (S.5) - A-Level at Kahinju Senior Secondary School (Ref KSS-2026-0003).\r\nOur office will contact you soon with the next steps. Thank you.\r\n- Kahinju S.S.S Administration', '2026-11-16 07:00:56', '2026-11-16 07:00:21'),
(2, 'KSS-2026-0002', 'Kyaboona Benard', 'Senior Five (S.5) - A-Level', 'Luwero secondary school', 'Muhumuza Nicholas', '0781 263670', '', 'please recieve the message', 'replied', 'Dear Muhumuza Nicholas,\r\nWe have received the application of Kyaboona Benard to Senior Five (S.5) - A-Level at Kahinju Senior Secondary School (Ref KSS-2026-0002).\r\nOur office will contact you soon with the next steps. Thank you.\r\n- Kahinju S.S.S Administration', '2026-11-15 13:14:50', '2026-11-15 13:13:28'),
