INSERT INTO `wp_kss_clubs` (`id`, `name`, `icon`, `description`, `photo`, `photo2`, `photo3`, `patron_name`, `patron_photo`, `sort_order`) VALUES
(1, 'THE PEER EDUCATION RWENZORI KAHINJU CLUB', '🎓', 'It is a profound privilege to introduce this piece, celebrating the mission and achievements of our peer education club. The peer Education club is not just another extracurricular activity; it is a movement.', '/wp-content/uploads/2026/11/WhatsApp-Image-2026-11-20-at-4.00.26-PM-1.jpeg', '', '', 'MUHENDA RICHARD PATRON, PEER EDUCATIONN RWENZORI KAHINJU CLUB', '/wp-content/uploads/2026/11/PATRON-BOYS-HOSTEL.JPG-1.jpeg', 1),
(3, 'Educate Club', '🌱', 'Learners work together on projects and activities that serve the school and the community.', '/wp-content/uploads/2026/11/880a1526-5ff2-47df-a534-bc1fac0d4dab.jpg', '', '', 'MADAM MARY GORRET PATRON EDUCATE CLUB KAHINJU SENIOR SECONDARY SCHOOL', '/wp-content/plugins/kahinju-core/assets/people/patron-educate-club.jpg', 2),
(5, 'THE SCOUTING CLUB OF KAHINJU', '🦁', 'It is of no lie that scouting club has greatly improved the lifestyles of everyone that trusted and embraced it. the club was introduced by our hero Lord Baden Powell in 1907 who was born in England in 1857', '/wp-content/uploads/2026/11/WhatsApp-Image-2026-11-20-at-3.59.57-PM.jpeg', '', '', 'PATRICK AKORA PATRON SCOUTING CLUB OF KAHINJU', '/wp-content/uploads/2026/11/WhatsApp-Image-2026-11-20-at-4.58.49-PM.jpeg', 3),
(7, 'THE DEBATE CLUB', '🎙️', 'Our club is built on the Foundational belief that eloquence, backed by research and critical thinking, is a superpower. We are not merely a club that argues.', '/wp-content/uploads/2026/11/WhatsApp-Image-2026-11-20-at-6.24.53-PM.jpeg', '', '', 'ITHUNGU STELLA PARTON DEBATE CLUB', '/wp-content/uploads/2026/11/WhatsApp-Image-2026-11-20-at-6.07.48-PM-1.jpeg', 4),
(9, 'THE CULTURAL HERITAGE CLUB, KAHINJU SECONDARY SCHOOL', '🪘', 'The cultural heritage club was established with clear purpose: to inspire students to appreciate the roots, understand their identity and promote unity through cultural expression.', '/wp-content/uploads/2026/11/WhatsApp-Image-2026-11-20-at-6.07.44-PM.jpeg', '', '', 'MR SUNDAY ROBERT PARTON CULTURAL HERITAGE CLUB KAHINJU SECONDARY SCHOOL', '', 5);
INSERT INTO `wp_kss_departments` (`id`, `name`, `description`, `photo`) VALUES
(1, 'Sciences', 'Biology, Chemistry, Physics and Mathematics build strong problem-solving skills.', '/wp-content/plugins/kahinju-core/assets/gallery/kahinju-m3-16.jpg'),
(2, 'Arts and Humanities', 'History, Geography and Religious Education help learners understand people and society.', '/wp-content/plugins/kahinju-core/assets/gallery/kahinju-m3-21.jpg'),
(3, 'Languages', 'English, Literature and Kiswahili develop confident speaking, reading and writing.', '/wp-content/plugins/kahinju-core/assets/gallery/kahinju-m3-19.jpg'),
(4, 'ICT and Practical Studies', 'Computer studies, agriculture and entrepreneurship prepare learners for real life.', '/wp-content/plugins/kahinju-core/assets/gallery/kahinju-m3-17.jpg'),
(5, 'Vocational & Business', 'Covers practical and commercial subjects required under Uganda\'s competence-based curriculum, such as Entrepreneurship Education.', NULL),
(6, 'Guidance & Counseling', 'Oversees student welfare, career guidance for Senior 4 and Senior 6 candidates, and school health sensitization programs.', NULL);
INSERT INTO `wp_kss_events` (`id`, `title`, `event_date`, `venue`, `description`) VALUES
(1, 'Social & Digital Channels', '2026-11-21', 'Site', 'You can find student-led highlights, clips, and school updates on the Kahinju Senior Secondary School YouTube Channel and the Kahinju SSS Facebook Page'),
(2, '\"The Royals\" 2026 Prom Party', '2026-11-30', 'School grounds', 'Students celebrated the annual prom in Fort Portal with red-carpet arrivals, formal wear, and group performances'),
(3, 'Youth & Cultural Activities', '2026-12-26', 'School grounds', 'The school regularly hosts vibrant student events, youth culture rallies, and programs like the Hi-Skool Kiromo and Smashed Live anti-drug/alcohol education campaigns'),
(4, 'City HIV/AIDS & Teenage Pregnancy Campaign', '2026-11-24', 'School grounds', 'Fort Portal City Health Office officials visited Kahinju Secondary School on October 8, 2026. They held student sensitization sessions focused on HIV testing, prevention, and preventing teenage pregnancy'),
(5, 'Christmas carols', '2026-11-25', 'Kahinju S.S.S', 'Join us for Christmas carols at school.'),
(6, 'Students break off for the term', '2026-12-04', 'Kahinju S.S.S', 'Students go home at the end of the term.');
