INSERT INTO `wp_kss_leaders` (`id`, `role`, `name`, `message`, `photo`, `layout`, `sort_order`) VALUES
(1, 'Chairperson, Board of Governors', 'Rev. Abigaba Robert Atwooki', 'It is with great pride that I welcome you to the website of Kahinju Senior Secondary School, Fort Portal.\n\nThis website marks an important milestone in the life of our school, providing a platform to celebrate our achievements, and to share and document our journey as a learning community.\n\nKahinju Senior Secondary School is an institution built on a strong foundation of Christianity, discipline, academic excellence and moral integrity. The school has nurtured young men and women of character, confidence and competence who continue to make meaningful contributions to society.\n\nThe Board of Governors remains committed to providing sound governance and strategic leadership to ensure that the school continues to grow and thrive. Working closely with the headteacher, Mr. Patrick Akora, and the school administration, we support initiatives that enhance quality teaching and learning, promote responsible management of resources, improve infrastructure and safeguard the welfare of students and staff.\n\nAs our motto says, Ready to Serve.', '/wp-content/plugins/kahinju-core/assets/people/chairperson.jpg', 'featured', 1),
(3, 'Head of Humanities Department', 'MR KAGENDA FRANCIS', 'As the Head of Department for Humanities at Kahinju Senior Secondary School, I can state with pride that our department has been, and remains, a crucial basis for developing critical thinkers and global citizens since the very start of this institution.\r\n\r\nThe Humanities subjects, encompassing History, Geography and Christian Religious Education, are taught competently at both O-Level and A-Level by a team of highly equipped and dedicated teachers.', '/wp-content/plugins/kahinju-core/assets/people/head-humanities.jpg', 'featured', 2),
(5, 'Head of Biological Sciences Department', 'HALEMIMANA JEROME', 'To our valued students who inspire us, the devoted staff who guide and mentor them, cherished parents, and the entire Kahinju community: it is my honour to present this message on behalf of the Department of Biological Sciences at Kahinju Senior Secondary School through this website.\r\n\r\nOur department brings together three interrelated disciplines, Biology, Chemistry and Physical Education, each contributing uniquely to the holistic development of our learners.', '/wp-content/plugins/kahinju-core/assets/people/head-biological-sciences.jpg', 'featured', 3);
